{
  "name": "Mercury步进电机多轴运动控制器",
  "name_en": "Mercury Stepper Motor Multi-Axis Motion Controller",
  "manufacturer": "Physik Instrumente (PI)",
  "description": "这是一种用于驱动和控制多轴步进电机定位平台的精密运动控制器，常与电动样品台、显微镜位移台或其他线性/旋转轴配合使用。它支持位置移动、位置与运动状态读取、速度设置、软件限位以及摇杆手动控制，常用于显微成像、精密定位和自动化实验平台。",
  "description_en": "This is a precision multi-axis motion controller for driving and controlling stepper-motor positioning stages. It is commonly used with motorized sample stages, microscope translation stages, or other linear/rotary axes. It supports position moves, position and motion-status readback, velocity setting, software travel limits, and joystick manual control, making it useful in microscopy, precision positioning, and laboratory automation setups.",
  "tag_hints": [
    "stepper motor positioning",
    "multi-axis motion control",
    "motorized stage",
    "microscope stage positioning",
    "joystick control",
    "soft limits",
    "PI GCS"
  ],
  "actions": [
    {
      "action_name": "auto-run_cmd",
      "description": "向运动控制器发送原始命令。",
      "description_en": "Send a raw command to the motion controller."
    },
    {
      "action_name": "auto-query",
      "description": "查询指定轴的参数或状态。",
      "description_en": "Query a parameter or status for the specified axis."
    },
    {
      "action_name": "auto-set",
      "description": "设置指定轴的参数。",
      "description_en": "Set a parameter for the specified axis."
    },
    {
      "action_name": "auto-SetSoftLimits",
      "description": "定义指定轴的软件行程限位。",
      "description_en": "Define software travel limits for the specified axis."
    },
    {
      "action_name": "auto-ReInit",
      "description": "重新初始化运动控制器。",
      "description_en": "Reinitialize the motion controller."
    },
    {
      "action_name": "auto-MoveTo",
      "description": "将指定通道移动到目标位置。",
      "description_en": "Move the specified channel to a target position."
    },
    {
      "action_name": "auto-GetPos",
      "description": "获取指定通道的当前位置。",
      "description_en": "Get the current position of the specified channel."
    },
    {
      "action_name": "auto-IsMoving",
      "description": "获取指定通道是否正在运动。",
      "description_en": "Get whether the specified channel is moving."
    },
    {
      "action_name": "auto-IsOnTarget",
      "description": "获取各轴是否到达目标位置。",
      "description_en": "Get whether the axes are on target."
    },
    {
      "action_name": "auto-RefreshPos",
      "description": "刷新各通道的位置读数。",
      "description_en": "Refresh position readings for the channels."
    },
    {
      "action_name": "auto-GetLastPos",
      "description": "获取指定通道最近一次记录的位置。",
      "description_en": "Get the last recorded position of the specified channel."
    },
    {
      "action_name": "auto-SetJoystick",
      "description": "设置摇杆手动控制的开关及作用通道。",
      "description_en": "Set the joystick manual-control state and active channels."
    },
    {
      "action_name": "auto-GetVelocity",
      "description": "获取指定通道的运动速度设定。",
      "description_en": "Get the motion velocity setting of the specified channel."
    },
    {
      "action_name": "auto-SetVelocity",
      "description": "设置指定通道的运动速度。",
      "description_en": "Set the motion velocity of the specified channel."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "获取控制器是否就绪。",
      "description_en": "Get whether the controller is ready."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "获取通道对应的控制对象。",
      "description_en": "Get the control object associated with the channel."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "获取通道的相位或阶段状态。",
      "description_en": "Get the phase or stage status of the channel."
    },
    {
      "action_name": "auto-GetMin",
      "description": "获取指定通道的最小位置限值。",
      "description_en": "Get the minimum position limit of the specified channel."
    },
    {
      "action_name": "auto-GetMax",
      "description": "获取指定通道的最大位置限值。",
      "description_en": "Get the maximum position limit of the specified channel."
    },
    {
      "action_name": "auto-Cleanup",
      "description": "执行设备连接清理与关闭。",
      "description_en": "Clean up and close the device connection."
    }
  ]
}

